regions = {
    (0, 0): [[2, 2], [9, 9]],
    (0, 1): [[9, 2], [9, 2]],
    (1, 0): [[9, 2], [2, 2]],
    (1, 1): [[2, 2], [2, 9]],
    (2, 0): [[2, 9], [9, 2]],
    (2, 1): [[2, 2], [9, 2]],
}

categories = {}
for (c, r), region in sorted(regions.items()):
    row0_uniform = region[0][0] == region[0][1]
    row1_uniform = region[1][0] == region[1][1]
    col0_uniform = region[0][0] == region[1][0]
    col1_uniform = region[0][1] == region[1][1]
    checker = (region[0][0] == region[1][1]) and (region[0][1] == region[1][0])

    # MoreCategories for classification
    if row0_uniform and row1_uniform:
        category = "rows_uniform"
    elif col0_uniform and col1_uniform:
        category = "cols_uniform"
    elif checker:
        category = "checkerboard"
    elif row0_uniform:
        category = "row0_uniform"
    elif row1_uniform:
        category = "row1_uniform"
    elif col0_uniform:
        category = "col0_uniform"
    elif col1_uniform:
        category = "col1_uniform"
    else:
        category = "none"

    categories[(c, r)] = category
    print(f"Region ({c},{r}): category={category}, rows_uniform={row0_uniform}/{row1_uniform}, cols_uniform={col0_uniform}/{col1_uniform}, checker={checker}")

print("\nCategory summary:")
from collections import Counter
print(Counter(categories.values()))

